  const menu=document.querySelector('.account-menu');if(menu&&!menu.querySelector('[data-ops-center]')){const b=document.createElement('button');b.type='button';b.dataset.opsCenter='';b.setAttribute('role','menuitem');b.innerHTML=svgIcon('<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>')+'消息通知<span class="ops-unread-dot"></span>';b.onclick=center;const logout=menu.querySelector('[data-account-signout]');logout?menu.insertBefore(b,logout):menu.append(b)}
  const unread=['announcement','update'].some(k=>config[k]?.enabled&&!read(k));document.querySelectorAll('[data-ops-center]').forEach(b=>b.classList.toggle('has-unread',unread));
