 function saved(r){return (prefs.extensionInbox||[]).some(x=>x.item?.[1]===r.url)||data.some(s=>s.scenes.some(c=>c.groups.some(g=>g.items.some(i=>i[1]===r.url))))}
 function followButton(id){return `<button class="world-button world-follow" data-w-follow="${e(id)}" aria-pressed="${isFollowed(id)}">${icon(isFollowed(id)?'check':'plus')}<span>${isFollowed(id)?'已关注':'关注合集'}</span></button>`}
 function resourceCard(r){return `<article class="world-resource"><a href="${e(urlSafe(r.url))}" target="_blank" rel="noopener noreferrer" class="world-resource-link"><span class="world-site-mark" data-topic="${e(r.topic)}">${e(r.mark)}</span><span><strong>${e(r.name)}</strong><small>${e(r.type)}</small></span>${icon('external')}<p>${e(r.desc)}</p></a><div class="world-resource-foot"><span>${e(topicLabel(r.topic))}</span><button class="world-save" data-w-save="${e(r.id)}" aria-label="${saved(r)?'已收藏':'收藏'} ${e(r.name)}" title="${saved(r)?'已在我的收藏中':'收藏到稍后整理'}">${icon(saved(r)?'check':'save')}</button></div></article>`}
 function collectionCard(c){return `<article class="world-collection" data-tone="${e(c.tone)}"><button class="world-collection-main" data-w-open="collection" data-w-id="${e(c.id)}"><div class="world-collection-art">${icon(c.icon)}<span class="world-art-ring"></span><span class="world-art-dots"></span><small>${e(c.eyebrow)}</small></div><div class="world-collection-copy"><span class="world-kicker">${e(c.source)}</span><h3>${e(c.title)}</h3><p>${e(c.subtitle)}</p><div><small>${c.resourceIds.length} 个资源 · ${e(topicLabel(c.topic))}</small>${icon('arrow')}</div></div></button></article>`}
